using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluatorClient = null!;

    [ClassInitialize]
    public static async Task ClassInit(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        var app = await _appHost.BuildAsync();
        await app.StartAsync();

        _chatClient = app.Services.GetRequiredService<IChatClient>();
        _evaluatorClient = app.Services.GetRequiredService<IChatClient>();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is IAsyncDisposable disposable)
            await disposable.DisposeAsync();
    }

    [TestMethod]
    public async Task Greeting_IsRelevantAndCoherent()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, who are you?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var evaluators = CreateEvaluators();
        var result = await EvaluateAsync(messages, evaluators);

        AssertAllPassed(result);
    }

    [TestMethod]
    public async Task FactualQuestion_IsGroundedAndRelevant()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var evaluators = CreateEvaluators();
        var result = await EvaluateAsync(messages, evaluators);

        AssertAllPassed(result);
    }

    [TestMethod]
    public async Task MultiTurn_MaintainsContext()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));
        response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var evaluators = CreateEvaluators();
        var result = await EvaluateAsync(messages, evaluators);

        AssertAllPassed(result);
    }

    private static IList<IEvaluator> CreateEvaluators()
    {
        return
        [
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
        ];
    }

    private static async Task<EvaluationResult> EvaluateAsync(
        IList<ChatMessage> messages,
        IList<IEvaluator> evaluators)
    {
        var result = new EvaluationResult();
        foreach (var evaluator in evaluators)
        {
            var scores = await evaluator.EvaluateAsync(messages, _evaluatorClient);
            foreach (var kvp in scores)
            {
                result.Add(kvp.Key, kvp.Value);
            }
        }

        return result;
    }

    private static void AssertAllPassed(EvaluationResult result)
    {
        foreach (var (metric, value) in result)
        {
            if (value is NumericMetricValue numeric)
            {
                Assert.IsTrue(
                    numeric.Value >= 3,
                    $"Metric '{metric}' scored {numeric.Value}, expected >= 3.");
            }
        }
    }
}

